// Full Qi XP is a hard stop. The one-point promotion step can only be
// committed by a successful pill transaction; ordinary XP sources clamp first.
export const ZHUJI_FULL_XP = 1800
export const JINDAN_FULL_XP = 6600
export const cultivationXpCap = xp => xp <= ZHUJI_FULL_XP ? ZHUJI_FULL_XP
  : xp <= JINDAN_FULL_XP ? JINDAN_FULL_XP : TOWER_XP_CAP
export function cultivationLevelXp(level) {
  const n = level - 1
  return level === 11 ? ZHUJI_FULL_XP + 1
    : level === 21 ? JINDAN_FULL_XP + 1 : 30 * n + 15 * n * n
}
export function useZhujiPill(state, id = 'zhuji') {
  const item = CAMP_PILLS[id]
  if (!item?.successChance) return fail('unknown-pill')
  if (state.xp > item.gate) return fail(id === 'zhuji' ? 'already-zhuji' : 'wrong-realm')
  if (state.xp !== item.gate) return fail('breakthrough-not-ready')
  if (!(state.pills[id] > 0)) return fail('no-pill')
  let rng = state.breakthroughRng
  rng ^= rng << 13; rng ^= rng >>> 17; rng ^= rng << 5
  state.breakthroughRng = rng >>> 0
  const success = state.breakthroughRng / 0x100000000 < item.successChance
  state.pills[id]--
  if (success) state.xp = item.gate + 1
  return { ok: true, id, success, itemName: item.name, target: item.target, successChance: item.successChance, cultivation: cultivationAt(state.xp) }
}
