export function cultivationAt(xp, legacy = false) {
  if (!integer(xp, TOWER_XP_CAP)) throw new RangeError('Invalid tower cultivation')
  let level = 1
  while (level < 30 && xp >= cultivationLevelXp(level + 1)) level++
  const stage = Math.floor((level - 1) / 10), minorSteps = level - 1 - stage
  const multiplier = legacy ? 1 + 0.2 * (level - 1) / 29 : 1.08 ** minorSteps * 1.35 ** stage
  const full = xp === cultivationXpCap(xp)
  return {
    level,
    realm: ['炼气', '筑基', '金丹'][stage],
    layer: (level - 1) % 10 + 1,
    consummated: full,
    breakthroughReady: full && xp < TOWER_XP_CAP,
    xpStart: cultivationLevelXp(level),
    xpEnd: level % 10 === 0 ? cultivationXpCap(xp) : cultivationLevelXp(level + 1),
    maxHp: legacy ? 100 * multiplier : 100 * 1.08 ** minorSteps * 1.35 ** stage,
    attackMultiplier: multiplier,
    capped: xp === TOWER_XP_CAP,
  }
}

